<?php $headings=['services'=>'Bakım deneyimlerimiz','service'=>$service['name']??'Bakımınız','experts'=>'Bakımın arkasındaki uzmanlar','about'=>'Özenle ayrılan zaman','contact'=>'Bize ulaşın','reviews'=>'Bakım deneyimleri']; ?>
<section class="container py-5"><p class="eyebrow">LUMÉRA BEAUTY</p><h1><?= e($headings[$page]) ?></h1><p class="muted">Örnek katalog fiyatlarıdır; gerçek işletme tarifesi değildir. İllüstrasyonlu örnek uzmanlar kurgusaldır.</p>
