<?php elseif($page==='about'): ?><div class="customer-card mt-4"><p class="lead">Luméra Beauty, güzellik merkezindeki bakım planlamasını tek bir yerde buluşturur.</p><p>Güncel hizmetleri inceleyebilir, uygun uzman ve saati seçebilir, bakım geçmişinizi hesabınızdan takip edebilirsiniz.</p><a class="btn btn-lumera" href="<?= e(url('services')) ?>">Bakımları keşfedin</a></div>
<?php elseif($page==='contact'): ?><div class="customer-card mt-4"><h2 class="h4">Merkez iletişim telefonu</h2><?php if($phone): ?><p><?= e($phone) ?></p><?php if(preg_match('/^[+0-9 ()-]+$/',$phone)): ?><a class="btn btn-outline-dark" href="tel:<?= e(preg_replace('/[^+0-9]/','',$phone)) ?>">Merkezi arayın</a><?php endif ?><?php else: ?><p>İletişim telefonu henüz yayınlanmadı. Randevularınızı hesabınızdan yönetebilirsiniz.</p><?php endif ?><a class="btn btn-lumera ms-2" href="<?= e(booking_url()) ?>">Online randevu</a></div>
<?php else: ?><div class="row g-4 mt-3"><?php foreach($reviews as$r): ?><article class="col-md-6"><div class="customer-card"><h2 class="h5"><?= e($r['service_name']) ?> · <?= (int)$r['rating'] ?> / 5</h2><p><?= e($r['comment']) ?></p><small><?= e(mb_substr($r['name'],0,1)) ?>. · Doğrulanmış tamamlanan randevu</small></div></article><?php endforeach ?></div><?php if(!$reviews): ?><p class="muted mt-4">Henüz yayınlanmış değerlendirme bulunmuyor.</p><?php endif ?><?php endif ?>
